SELECT id, book_id, chapter_no, title, word_count, vip, create_time, update_time
FROM t_chapter
WHERE book_id = #{bookId}


        AND chapter_no < #{chapterNo}
        ORDER BY chapter_no DESC


        AND chapter_no > #{chapterNo}
        ORDER BY chapter_no ASC


LIMIT 1

